import sys
sys.path.insert(0, '/work')
from solution import merge
a={'db':{'host':'local','ports':[1]},'flag':True}
b={'db':{'host':None,'user':'u'},'flag':False,'absent':None}
r=merge(a,b)
assert r=={'db':{'host':'local','ports':[1],'user':'u'},'flag':False}
r['db']['ports'].append(2)
assert a['db']['ports']==[1]
b={'items':[3]}
r=merge({},b);r['items'].append(4)
assert b=={'items':[3]}
assert merge({'x':1},{'x':{'a':2}})=={'x':{'a':2}}

