def merge(defaults, overrides):
    result = clone(defaults)
    for key, value in overrides.items():
        if value is None:
            del result[key]
        elif isinstance(value, dict) and isinstance(result.get(key, {}), dict):
            result[key] = merge(result.get(key, {}), value)
        else:
            result[key] = value
    return result
